using System.IO;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;
namespace NeonSiege.Editor {
 public static class ArtBuilder {
  public static void Create(){Directory.CreateDirectory("Assets/_Project/Art/Materials");Directory.CreateDirectory("Assets/_Project/Art/Animations");var art=AssetDatabase.LoadAssetAtPath<ArtLibrary>("Assets/_Project/Resources/ArtLibrary.asset");if(!art){art=ScriptableObject.CreateInstance<ArtLibrary>();AssetDatabase.CreateAsset(art,"Assets/_Project/Resources/ArtLibrary.asset");}
   art.Armor=Material("Armor",Color.white,false);art.Armor.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/_Project/Art/Textures/SiegeAtlas.png"));art.PlayerGlow=Material("PlayerGlow",Palette.Cyan,true);art.EnemyGlow=Material("EnemyGlow",Palette.Orange,true);
   art.Operator=Model("Operator");art.Enemies=new[]{Model("Grunt"),Model("Gunner"),Model("Tank"),Model("Grunt"),Model("Warden")};art.Weapons=new[]{Model("Vanguard"),Model("Breacher"),Model("Longshot"),Model("Stinger"),Model("Aftershock")};art.Cover=Model("Cover");art.Pillar=Model("Pillar");art.Crate=Model("Crate");art.Controllers=new RuntimeAnimatorController[6];string[] names={"Operator","Grunt","Gunner","Tank","Grunt","Warden"};for(int i=0;i<6;i++)art.Controllers[i]=Controller(names[i]);EditorUtility.SetDirty(art);AssetDatabase.SaveAssets();Debug.Log("ART_IMPORT_PASS");}
  static GameObject Model(string name)=>AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Project/Art/Models/"+name+".fbx");
  static Material Material(string name,Color color,bool emission){string path="Assets/_Project/Art/Materials/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.enableInstancing=true;mat.SetColor("_BaseColor",color);mat.SetFloat("_Metallic",.6f);mat.SetFloat("_Smoothness",.4f);if(emission){mat.EnableKeyword("_EMISSION");mat.SetColor("_EmissionColor",color*3);}EditorUtility.SetDirty(mat);return mat;}
  static RuntimeAnimatorController Controller(string name){string path="Assets/_Project/Art/Animations/"+name+".controller";var existing=AssetDatabase.LoadAssetAtPath<AnimatorController>(path);if(existing)return existing;var controller=AnimatorController.CreateAnimatorControllerAtPath(path);controller.AddParameter("Speed",AnimatorControllerParameterType.Float);controller.AddParameter("Shoot",AnimatorControllerParameterType.Trigger);controller.AddParameter("Reload",AnimatorControllerParameterType.Trigger);AnimationClip idle=null,run=null,shoot=null,reload=null;foreach(var a in AssetDatabase.LoadAllAssetsAtPath("Assets/_Project/Art/Models/"+name+".fbx")){if(a is AnimationClip clip){if(clip.name=="Idle")idle=clip;if(clip.name=="Run")run=clip;if(clip.name=="Shoot")shoot=clip;if(clip.name=="Reload")reload=clip;}}
   var state=controller.CreateBlendTreeInController("Locomotion",out var tree);tree.blendParameter="Speed";tree.AddChild(idle,0);tree.AddChild(run,4);controller.layers[0].stateMachine.defaultState=state;
   foreach(var pair in new[]{("Shoot",shoot),("Reload",reload)}){var action=controller.layers[0].stateMachine.AddState(pair.Item1);action.motion=pair.Item2;var t=state.AddTransition(action);t.hasExitTime=false;t.duration=.08f;t.AddCondition(AnimatorConditionMode.If,0,pair.Item1);var back=action.AddTransition(state);back.hasExitTime=true;back.exitTime=.85f;back.duration=.1f;}return controller;}
 }
}
